package com.shopsphere;import jakarta.servlet.http.HttpServletRequest;import java.time.Instant;import java.util.*;import org.springframework.http.*;import org.springframework.web.bind.MethodArgumentNotValidException;import org.springframework.web.bind.annotation.*;class NotFoundException extends RuntimeException{NotFoundException(String m){super(m);}}class BusinessException extends RuntimeException{BusinessException(String m){super(m);}}class CouponException extends RuntimeException{CouponException(String m){super(m);}}class CouponConflictException extends RuntimeException{CouponConflictException(String m){super(m);}}class MissingIdempotencyKeyException extends RuntimeException{MissingIdempotencyKeyException(String m){super(m);}}class IdempotencyConflictException extends RuntimeException{IdempotencyConflictException(String m){super(m);}}class IdempotencyInProgressException extends RuntimeException{IdempotencyInProgressException(String m){super(m);}}record ApiError(Instant timestamp,int status,String error,String message,String path,Map<String,String>validationErrors){}@RestControllerAdvice class Errors{@ExceptionHandler(MethodArgumentNotValidException.class)ResponseEntity<ApiError>v(MethodArgumentNotValidException e,HttpServletRequest r){Map<String,String>m=new LinkedHashMap<>();e.getBindingResult().getFieldErrors().forEach(x->m.putIfAbsent(x.getField(),x.getDefaultMessage()));return out(HttpStatus.BAD_REQUEST,"Validation failed",r,m);}@ExceptionHandler({MissingIdempotencyKeyException.class,CouponException.class,AddressResolutionException.class})ResponseEntity<ApiError>bad(RuntimeException e,HttpServletRequest r){return out(HttpStatus.BAD_REQUEST,e.getMessage(),r,Map.of());}@ExceptionHandler({BusinessException.class,CouponConflictException.class,IdempotencyConflictException.class,IdempotencyInProgressException.class})ResponseEntity<ApiError>b(RuntimeException e,HttpServletRequest r){return out(HttpStatus.CONFLICT,e.getMessage(),r,Map.of());}@ExceptionHandler({ProductPricingException.class,InventoryCommunicationException.class})ResponseEntity<ApiError>downstream(RuntimeException e,HttpServletRequest r){return out(HttpStatus.SERVICE_UNAVAILABLE,e.getMessage(),r,Map.of());}@ExceptionHandler(NotFoundException.class)ResponseEntity<ApiError>n(NotFoundException e,HttpServletRequest r){return out(HttpStatus.NOT_FOUND,e.getMessage(),r,Map.of());}private ResponseEntity<ApiError>out(HttpStatus s,String m,HttpServletRequest r,Map<String,String>v){return ResponseEntity.status(s).body(new ApiError(Instant.now(),s.value(),s.getReasonPhrase(),m,r.getRequestURI(),v));}}
